import{_ as n,o as i,c as a,a3 as t}from"./chunks/framework.DX_KL3e0.js";const p=JSON.parse('{"title":"Đầu Mối Liên Hệ","description":"","frontmatter":{},"headers":[],"relativePath":"chuc-nang/dau-moi-lien-he.md","filePath":"chuc-nang/dau-moi-lien-he.md","lastUpdated":1782639524000}'),c={name:"chuc-nang/dau-moi-lien-he.md"};function o(l,h,e,r,u,g){return i(),a("div",null,[...h[0]||(h[0]=[t('<h1 id="đau-moi-lien-he" tabindex="-1">Đầu Mối Liên Hệ <a class="header-anchor" href="#đau-moi-lien-he" aria-label="Permalink to &quot;Đầu Mối Liên Hệ&quot;">​</a></h1><p>Phân hệ <strong>Đầu Mối Liên Hệ</strong> giúp người dùng tìm đúng người phụ trách cho từng mảng công việc, phòng ban hoặc đầu việc nội bộ.</p><div class="info custom-block"><p class="custom-block-title">Tóm tắt nhanh</p><ul><li><strong>Đường dẫn:</strong> <code>/tra-cuu/dau-moi</code>.</li><li><strong>Ai dùng được:</strong> người có quyền xem đầu mối liên hệ.</li><li><strong>Dùng để:</strong> tra cứu người phụ trách, đơn vị phụ trách và thông tin liên hệ nhanh.</li></ul></div><h2 id="giao-dien-chinh" tabindex="-1">Giao diện chính <a class="header-anchor" href="#giao-dien-chinh" aria-label="Permalink to &quot;Giao diện chính&quot;">​</a></h2><p>Trang hiển thị theo dạng danh sách hoặc thẻ thông tin, mỗi mục thường có:</p><ul><li>Tên người phụ trách</li><li>Chức vụ</li><li>Phòng ban</li><li>Mảng phụ trách</li><li>Thông tin liên hệ cơ bản</li></ul><h2 id="cac-thao-tac-chinh" tabindex="-1">Các thao tác chính <a class="header-anchor" href="#cac-thao-tac-chinh" aria-label="Permalink to &quot;Các thao tác chính&quot;">​</a></h2><h3 id="tim-nguoi-phu-trach" tabindex="-1">Tìm người phụ trách <a class="header-anchor" href="#tim-nguoi-phu-trach" aria-label="Permalink to &quot;Tìm người phụ trách&quot;">​</a></h3><ol><li>Mở <code>/tra-cuu/dau-moi</code>.</li><li>Tìm theo tên, phòng ban hoặc lĩnh vực phụ trách.</li><li>Mở thẻ thông tin để xem chi tiết.</li></ol><h3 id="dung-trong-van-hanh-hang-ngay" tabindex="-1">Dùng trong vận hành hằng ngày <a class="header-anchor" href="#dung-trong-van-hanh-hang-ngay" aria-label="Permalink to &quot;Dùng trong vận hành hằng ngày&quot;">​</a></h3><p>Phân hệ này phù hợp khi bạn cần biết:</p><ul><li>liên hệ ai để xử lý một nhóm công việc</li><li>ai đang phụ trách một đơn vị hoặc đầu việc cụ thể</li><li>nên chuyển ticket hay yêu cầu cho ai</li></ul><h3 id="cap-nhat-đau-moi" tabindex="-1">Cập nhật đầu mối <a class="header-anchor" href="#cap-nhat-đau-moi" aria-label="Permalink to &quot;Cập nhật đầu mối&quot;">​</a></h3><p>Người có quyền quản lý có thể chỉnh sửa lại thông tin đầu mối khi có thay đổi nhân sự hoặc thay đổi phạm vi phụ trách.</p><div class="warning custom-block"><p class="custom-block-title">WARNING</p><p>Đầu mối liên hệ chỉ hữu ích khi dữ liệu luôn mới. Nếu có thay đổi người phụ trách mà chưa cập nhật, nên báo Admin hoặc bộ phận vận hành hệ thống sớm.</p></div><h2 id="cau-hoi-thuong-gap" tabindex="-1">Câu hỏi thường gặp <a class="header-anchor" href="#cau-hoi-thuong-gap" aria-label="Permalink to &quot;Câu hỏi thường gặp&quot;">​</a></h2><p><strong>Tôi không thấy một đầu mối mà mình cần tìm?</strong><br> Có thể dữ liệu chưa được khai báo hoặc tài khoản của bạn không có quyền xem nhánh đó.</p><p><strong>Đầu mối liên hệ có thay thế sơ đồ tổ chức không?</strong><br> Không. Đây là danh bạ tác nghiệp, còn sơ đồ tổ chức vẫn là nơi thể hiện cấu trúc quản lý chính thức.</p><hr><p><em>Liên quan:</em> <a href="/help/chuc-nang/tra-cuu.html">Tra cứu</a> · <a href="/help/chuc-nang/to-chuc.html">Tổ chức</a> · <a href="/help/chuc-nang/tickets.html">Ticket Hỗ Trợ</a></p>',20)])])}const d=n(c,[["render",o]]);export{p as __pageData,d as default};
